#!/usr/bin/env bash
# Creates the initial MAREA backlog. Review this file before executing it.
set -euo pipefail

REPO="mariaherrerosanchez/Proyecto10_MAREA_MariaHerrero"
PROJECT_NUMBER=2
PROJECT_OWNER="mariaherrerosanchez"
created=0
skipped=0

command -v gh >/dev/null 2>&1 || { echo "Error: GitHub CLI (gh) no está disponible." >&2; exit 1; }
gh auth status >/dev/null 2>&1 || { echo "Error: GitHub CLI no está autenticado." >&2; exit 1; }

issue_in_project() {
  local issue_url="$1"
  gh project item-list "$PROJECT_NUMBER" --owner "$PROJECT_OWNER" --limit 1000 --format json \
    --jq ".items[] | select(.content.url == \"$issue_url\") | .id" | grep -q .
}

add_issue_to_project() {
  local title="$1" issue_url="$2"
  if issue_in_project "$issue_url"; then
    echo "Ya pertenece al Project #$PROJECT_NUMBER: $title"
  else
    gh project item-add "$PROJECT_NUMBER" --owner "$PROJECT_OWNER" --url "$issue_url" >/dev/null
    echo "Añadida al Project #$PROJECT_NUMBER (estado predeterminado Backlog): $title"
  fi
}

create_issue() {
  local title="$1" epic_code="$2" epic_name="$3" epic_label="$4" milestone="$5" priority="$6" role="$7" goal="$8" value="$9" criteria="${10}" dependencies="${11:-}"
  local issue_id existing_issue existing_title issue_url body information
  issue_id="${title%% — *}"
  existing_issue="$(gh issue list --repo "$REPO" --state all --search "$issue_id in:title" --limit 1000 --json title,url --jq ".[] | select(.title | startswith(\"$issue_id —\")) | [.title, .url] | @tsv")"
  if [[ -n "$existing_issue" ]]; then
    IFS=$'\t' read -r existing_title issue_url <<< "$existing_issue"
    if [[ "$existing_title" == "$title" ]]; then
      echo "Omitida (ya existe): $title"
    else
      echo "Omitida (US existente con título pendiente de sincronizar): $existing_title"
    fi
    add_issue_to_project "$title" "$issue_url"
    ((skipped+=1))
    return
  fi
  information=$'- Épica: '"$epic_code"$' — '"$epic_name"$'\n- Milestone: '"$milestone"$'\n- Prioridad: '"$priority"
  if [[ -n "$dependencies" ]]; then
    information+=$'\n- Dependencias: '"$dependencies"
  fi
  body=$(cat <<EOF
## Historia de usuario

Como $role,
quiero $goal,
para $value.

## Criterios de aceptación

$criteria

## Información

$information
EOF
)
  issue_url="$(gh issue create --repo "$REPO" --title "$title" --body "$body" --milestone "$milestone" --label "$epic_label" --label "priority:$priority")"
  echo "Creada: $title"
  add_issue_to_project "$title" "$issue_url"
  ((created+=1))
}

